const BASE = 'https://api.lokalise.com/api2';
const JOBS = [
  { name: 'Personality.co', pid: '31393214664f295f94dd86.76792605',
    langs: [767,1056,10154,673,757,734,733,10152,10153,749,737,759,748,708,770,754,753,666] },
  { name: 'Members area', pid: '9933660066825e9a8005c8.58526829',
    langs: [765,761,768,818,793,773,799,10159,744,769,774] }
];
return JOBS.map(j => {
  const qs = [
    'limit=200',
    'page=1',
    'include_translations=1',
    'filter_untranslated=1',
    'filter_translation_lang_ids=' + j.langs.join(',')
  ].join('&');
  return { json: { name: j.name, pid: j.pid, langs: j.langs, url: BASE + '/projects/' + j.pid + '/keys?' + qs } };
});

const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const r = items[i].json || {};
  const b = r.body !== undefined ? r.body : r;
  const cfg = $('Config').all()[i].json;
  if (!Array.isArray(b.keys)) {
    out.push({ json: { name: cfg.name, ERROR: true, statusCode: r.statusCode, body: JSON.stringify(b).slice(0, 500) } });
    continue;
  }
  const total = Number((r.headers || {})['x-pagination-total-count'] || 0);
  const keys = b.keys;
  let archived = 0;
  const perLang = {};
  const platformCount = {};
  const nsCount = {};
  const samples = [];
  for (const k of keys) {
    if (k.is_archived) { archived++; continue; }
    for (const p of (k.platforms || [])) platformCount[p] = (platformCount[p] || 0) + 1;
    const kn = (k.key_name && (k.key_name.web || k.key_name.other || k.key_name.ios || k.key_name.android)) || '';
    const ns = kn.split(/[.:_]/)[0] || '(none)';
    nsCount[ns] = (nsCount[ns] || 0) + 1;
    let src = '';
    const missingHere = [];
    for (const t of (k.translations || [])) {
      if (t.language_iso === 'en') { src = t.translation; continue; }
      const empty = !t.translation || String(t.translation).trim() === '';
      if (empty) {
        perLang[t.language_iso] = (perLang[t.language_iso] || 0) + 1;
        missingHere.push(t.language_iso);
      }
    }
    if (samples.length < 30) {
      samples.push({ key: kn, chars: (src || '').length, src: String(src || '').slice(0, 180), missing_n: missingHere.length });
    }
  }
  const topNs = Object.entries(nsCount).sort((a, c) => c[1] - a[1]).slice(0, 20);
  out.push({ json: {
    name: cfg.name,
    statusCode: r.statusCode,
    untranslated_keys_total: total,
    page_keys: keys.length,
    archived_in_page: archived,
    platforms_in_page: platformCount,
    top_namespaces_in_page: topNs,
    missing_per_lang_in_page: perLang,
    samples: samples
  }});
}
return out;
